#!/usr/bin/env node
// Generates tests/fixtures/synthetic-100.json — a SYNTHETIC, TEST-ONLY graph payload
// (~100 entities, 4 chapters, identity edges with evidence) used via route interception
// to exercise cast overflow, ties overflow and graph legibility (FRONTEND_OVERHAUL §5
// Phase 4/5). It is never seeded into any database and never shipped as demo data.
// Deterministic (seeded PRNG) so the committed JSON is reproducible: `node make-synthetic.mjs`.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

let seed = 20260921;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];

const FIRST = ["Ael", "Bran", "Cael", "Dara", "Edric", "Fen", "Gwyn", "Hale", "Isolde", "Jory", "Kestrel", "Lior", "Maren", "Nym", "Orla", "Perrin", "Quill", "Rhoswen", "Sable", "Tamsin", "Ulric", "Vesper", "Wyn", "Yara", "Zev"];
const LAST = ["of the Marsh", "Ashvale", "Corvane", "the Younger", "Dunmere", "Ferrow", "Greylock", "Halloway", "of Isk", "Kell", "Lyre", "Morrow", "Nightingale", "Ostrey", "Pell"];

const nodes = [];
const edges = [];
let nid = 0;
let eid = 0;
const node = (type, label, first, subtype = null) => {
  nid += 1;
  nodes.push({ data: { id: `s${nid}`, label, type, subtype, importance: 1, first_seen_chapter: first, revealed_chapter: first, extraction_method: "gliner", evidence_span: `${label} (synthetic)`, properties: {} } });
  return `s${nid}`;
};
const edge = (source, target, relation, rev, quote) => {
  eid += 1;
  const tier = ["SAME_AS", "ALIAS", "SECRET_IDENTITY", "REINCARNATION", "TRANSMIGRATED_INTO"].includes(relation) ? 3 : relation === "RelatedTo" || ["Ally", "Enemy", "Rival", "Mentor", "Family", "Serves"].includes(relation) ? 2 : 1;
  edges.push({ data: { id: `se${eid}`, source, target, relation, tier, first_seen_chapter: rev, revealed_chapter: rev, extraction_method: tier === 3 ? "llm" : "gliner", evidence_span: quote ?? `synthetic evidence ${eid}` } });
};

// 70 people, 10 orders, 10 places, 8 items, 2 concepts, 1 event = 101
const people = [];
for (let i = 0; i < 70; i++) people.push(node("Character", `${FIRST[i % FIRST.length]} ${LAST[(i * 7) % LAST.length]}`, 1 + (i % 4)));
const orders = [];
for (let i = 0; i < 10; i++) orders.push(node("Organization", `the Order of ${pick(LAST)} ${i + 1}`, 1 + (i % 4)));
const places = [];
for (let i = 0; i < 10; i++) places.push(node("Place", `${pick(FIRST)}holm ${i + 1}`, 1 + (i % 4)));
const items = [];
for (let i = 0; i < 8; i++) items.push(node("Item", `the ${pick(LAST)} blade ${i + 1}`, 1 + (i % 4)));
node("Concept", "the Old Tongue", 1);
node("Concept", "Glassweaving", 2);
node("Event", "the Sundering", 3);

// hub: person 0 is the principal with ~20 ties (ties overflow > 12)
const hub = people[0];
const SOCIAL = ["Ally", "Enemy", "Rival", "Mentor", "Family", "Serves", "RelatedTo"];
for (let i = 1; i <= 20; i++) edge(hub, people[i], pick(SOCIAL), 1 + (i % 4));
// a sparse social web over people 1..59; people 60..69 are "minor figures": their ONLY
// tie is membership of an order, so under the Principal cast size they fold into it
// (§6.3 item 4) — the fixture must contain leaves or folding has nothing to test.
const LEAF_FROM = 60;
for (let i = 1; i < LEAF_FROM; i++) {
  const j = 1 + Math.floor(rnd() * (LEAF_FROM - 1));
  if (j !== i) edge(people[i], people[j], pick(SOCIAL), Math.max(1 + (i % 4), 1 + (j % 4)));
}
// structural
for (let i = 0; i < people.length; i++) {
  if (i % 3 === 0 || i >= LEAF_FROM) edge(people[i], orders[i % orders.length], "MemberOf", 1 + (i % 4));
  if (i >= LEAF_FROM) continue;
  if (i % 4 === 1) edge(people[i], places[i % places.length], "LocatedIn", 1 + (i % 4));
  if (i % 9 === 2) edge(people[i], items[i % items.length], "OwnsItem", 1 + (i % 4));
}
for (let i = 0; i < orders.length; i++) edge(orders[i], places[i], "LocatedIn", 1 + (i % 4));

// 5 identity edges, staggered reveals, each with evidence (citation gate)
edge(people[3], people[40], "SECRET_IDENTITY", 2, "the hooded rider was Dara Halloway all along");
edge(hub, people[45], "ALIAS", 3, "Ael and the Marsh Warden were one");
edge(people[10], people[50], "REINCARNATION", 3, "the child bore the old king's mark");
edge(people[20], people[60], "TRANSMIGRATED_INTO", 4, "she woke in the smith's body");
edge(people[5], people[65], "SAME_AS", 4, "two names, one hand on the ledger");
// one identity edge WITHOUT a quote — the §8.4 drop rule must remove it (and warn)
eid += 1;
edges.push({ data: { id: `se${eid}`, source: people[7], target: people[8], relation: "ALIAS", tier: 3, first_seen_chapter: 2, revealed_chapter: 2, extraction_method: "llm", evidence_span: null } });

const full = { slug: "the-hollow-crown", n: 4, elements: { nodes, edges }, _synthetic: "TEST FIXTURE ONLY — generated by make-synthetic.mjs, never demo data" };
const out = path.join(path.dirname(fileURLToPath(import.meta.url)), "synthetic-100.json");
fs.writeFileSync(out, JSON.stringify(full, null, 1));
console.log(`wrote ${out}: ${nodes.length} nodes, ${edges.length} edges`);
